"""Zoro (zoro.com) complete crawlable category inventory.

Captured 2026-10-15 from the authoritative first-party category tree rendered on
each department hub (the same ``window.INITIAL_STATE`` payload the spider walks
at crawl time: ``category.categoryData[<code>].b`` -> nested ``b`` children).
Every entry is a real Zoro leaf PLP URL of the form
``https://www.zoro.com/<slug>/c/<category-id>/``.

The inventory is the grouped ``{department: {leaf: {name, department, url,
category}}}`` mapping required by :class:`BaseListingSpider`, with **2189** leaves
across the **20** canonical departments. Leaf keys are the URL slug, which is
globally unique here (verified: 2,189 distinct slugs, zero cross-department
collisions), so the Airflow task id and GCS output path cannot clash.

The DAG schedules at most ``MAX_TASK_SUBCATEGORIES`` (3) leaves per department
through ``_spider_category_groups(..., group_by="department")``. ``-a
category=<leaf>`` selects one leaf; ``-a category=<department>`` remains a
legacy parent selector that fetches the department hub and live-walks its tree
(the hub URL for each department is in ``ZORO_DEPARTMENT_HUBS``).

Regenerate from the live department hubs; do not hand-edit.
"""

